// ffxi/target.h
namespace Ashita::FFXI
{
    struct arrowposition_t
    {
        float           X;
        float           Z;
        float           Y;
        float           W;
    };

    // PS2: CKaTarget
    struct targetentry_t
    {
        uint32_t        Index;                  // The target index.
        uint32_t        ServerId;               // The target server id.
        uintptr_t       EntityPointer;          // The target entity pointer.
        uintptr_t       ActorPointer;           // The target actor pointer.
        arrowposition_t ArrowPosition;          // The target arrow position. [IsArrowActive must be 1 to use this.]
        uint8_t         IsActive;               // Flag if the target is active.
        uint8_t         IsModelActor;           // Flag if the target entity is a model actor.
        uint8_t         IsArrowActive;          // Flag if the target free-floating arrow is active.
        uint8_t         unknown0023;            // Unknown. [Always 0x7F]
        uint16_t        Checksum;               // The target checksum.
        uint16_t        unknown0026;            // Unknown. [This used to be a mask of some sort.]
    };

    // PS2: CTkInputCtrl
    struct target_t
    {
        targetentry_t   Targets[2];             // m_MainTarget, m_OldTarget
        uint8_t         IsWalk;                 // Flag if the character is walking instead of running.
        uint8_t         IsAutoNotice;           // Flag if the game will automatically lock onto targets when engaging them. [The game refers to 'Locked On' as 'Notice'.]
        uint8_t         IsSubTargetActive;      // Flag if the sub target is active.
        uint8_t         DeactivateTarget;       // Flag if 1 will undo one step of the targeting windows.
        uint8_t         ModeChangeLock;         // Flag used when changing the menu locks while targeting.
        uint8_t         IsMouseRequestStack;    // Flag used in relation to the mouse.
        uint8_t         IsMouseRequestCancel;   // Flag used in relation to the mouse.
        uint8_t         IsPlayerMoving;         // Flag that is set whenever the character is moving (or trying to move).
        uint8_t         unknown0058;            // Unknown. [Flag set when targeting / untargeting.]
        uint8_t         unknown0059;            // Unknown. [Flag that changes the area display circle to show on the player instead of target.]
        uint8_t         unknown005A;            // Unknown.
        uint8_t         unknown005B;            // Unknown.
        uint32_t        LockedOnFlags;          // (IsNotice) Flags involved with being locked onto a target. [0x01 = locked on, 0x04 = locked on with sub-target.]
        uint32_t        SubTargetFlags;         // (targetType) Flags involving the sub-targets validity for an action or spell. (See notes below.)
        uint32_t        OldNotice;              // m_OldNotice
        uint16_t        DefaultMode;            // Unknown. [Related to the menu system.]
        uint16_t        MenuTargetLock;         // Unknown. [Related to the menu system.]
        uint8_t         ActionTargetActive;     // Flag if the target selection for an action is active.
        uint8_t         ActionTargetMaxYalms;   // The maximum distance of the current target selection in yalms for the given action. (FF means self-targeting only actions.)
        uint8_t         unknown006E;            // Unknown. [Related to action target.]
        uint8_t         unknown006F;            // Unknown. [Similar to ActionTargetActive, set to 1 when selecting a target.]
        uint8_t         unknown0070;            // Unknown. [Related to action target.]
        uint8_t         unknown0071;            // Unknown. [Related to action target.]
        uint8_t         unknown0072;            // Unknown. [Related to action target.]
        uint8_t         unknown0073;            // Unknown. [Related to action target.]
        uint8_t         IsMenuOpen;             // (TargetLock) Flag if any game menu is currently open.
        uint8_t         IsActionAoe;            // Flag if the select target action is aoe or not.
        uint8_t         ActionType;             // The select target action type. (ie. 42 = curing spells.)
        uint8_t         ActionAoeRange;         // The aoe range, in yalms, of the select target action.
        uint32_t        ActionId;               // The select target action id. (ie. 1 = Cure, 2 = Cure 2, etc.)
        uint32_t        ActionTargetServerId;   // The select target server id.
        uint16_t        unknown0080;            // Unknown. [Action related.]
        uint8_t         unknown0082;            // Unknown. [Action related.]
        uint8_t         unknown0083;            // Unknown. [Action related.]
        uint32_t        FocusTargetIndex;       // The current focus target index.
        uint32_t        FocusTargetServerId;    // The current focus target server id.
        float           TargetPosF[4];          // The mouse cursor position relative to the screen center. [Values are -1.0 to 1.0]
        int8_t          LastTargetName[25];     // The name of the entity last taken action on.
        uint8_t         padding00B5[3];         // Padding.
        uint32_t        LastTargetIndex;        // The last target index.       [Last target the player took action on.]
        uint32_t        LastTargetServerId;     // The last target server id.   [Last target the player took action on.]
        uint32_t        LastTargetChecksum;     // The last target checksum.    [Last target the player took action on.]
        uintptr_t       ActionCallback;         // Callback function. [Callback invoked when a given action is selected.]
        uintptr_t       CancelCallback;         // Callback function. [Callback invoked when cancelling an action selection.]
        uintptr_t       MyroomCallback;         // Callback function. [Callback invoked when selecting an exit door within a mog house.]
        uintptr_t       ActionAoeCallback;      // Callback function. [Callback invoked to display the area display for certain AoE actions.]
    };

    /*
    target_t Notes

        SubTargetFlags - This byte flag holds the valid target types that an action or spell can be used to target something with.
                         The bytes set depend on how an action is used. Either via the menu, typed or used with a <st> style token.

        TargetPosF     - This array holds the current mouse deltas from the center of the screen. The center of the screen is treated
                         as coord (0, 0) with each axis ranging from -1.0 to 1.0.
    */

    // PS2: CTkTarget
    struct targetwindow_t
    {
        // PS2: CTkMenuPrimitive
        uintptr_t       VTablePointer;
        uintptr_t       m_BaseObj;
        uintptr_t       m_pParentMCD;
        uint8_t         m_InputEnable;
        uint8_t         unknown000D;
        uint16_t        m_SaveCursol;
        uint8_t         m_Reposition;
        uint8_t         unknown0011[3];

        int8_t          Name[49];               // The targets name. [Window allows for longer than standard name length.]
        uint8_t         padding0045[3];         // Padding.
        uintptr_t       EntityPointer;          // The targets entity pointer.
        uint16_t        FrameChildrenOffsetX;   // The target window frame children objects x offset.
        uint16_t        FrameChildrenOffsetY;   // The target window frame children objects y offset.
        uint16_t        IconPositionX;          // The target window frame icon position. [Only the x axis is editable live.]
        uint16_t        IconPositionY;          // The target window frame icon position. [Only the x axis is editable live.]
        uint16_t        FrameOffsetX;           // The target window frame x offset. [Not editable live. Another address resets this value.]
        uint16_t        FrameOffsetY;           // The target window frame y offset. [Not editable live. Another address resets this value.]
        uint32_t        unknown0058;            // Unknown. [Position related.]
        uint32_t        LockShape;              // The locked-on CShape object pointer.
        uint32_t        ServerId;               // The targets server id.
        uint8_t         HPPercent;              // The targets health percent.
        uint8_t         DeathFlag;              // Flag that states the target is dead. Dims the health bar and sets it to 0 fill.
        uint8_t         ReraiseFlag;            // Dims the health bar when target is reraising. (Death flag must be set to 1.)
        uint8_t         padding0067;            // Padding.
        uint32_t        DeathNameColor;         // The target name color used when the target is dead.
        uint8_t         IsWindowLoaded;         // (m_helped) Flag that states if the target window is loaded and finished animating.
        uint8_t         padding006D[3];         // Padding.
        uint32_t        HelpString;             // The help string to display, if set, when opening the target window.
        uint32_t        HelpTitle;              // The help title to display, if set, when opening the target window. 
        uint32_t        m_pAnkShape[16];        // The target arrow and sub-target arrow Cshape object parts.
        uint8_t         m_Sub;                  // Flag if a sub-target is being selected; causes the sub-target name to show larger.
        uint8_t         unknown00B9;            // Unknown.
        uint8_t         m_AnkNum;               // The shape index to use from m_pAnkShape.
        uint8_t         unknown00BB;            // Unknown.
        int16_t         m_AnkX;                 // The main target arrow X position.
        int16_t         m_AnkY;                 // The main target arrow Y position.
        int16_t         m_SubAnkX;              // The sub target arrow X position.
        int16_t         m_SubAnkY;              // The sub target arrow Y position.
    };

    static_assert(sizeof(arrowposition_t) == 16, "Invalid 'arrowposition_t' structure size detected!");
    static_assert(sizeof(targetentry_t) == 40, "Invalid 'targetentry_t' structure size detected!");
    static_assert(sizeof(target_t) == 212, "Invalid 'target_t' structure size detected!");
    static_assert(sizeof(targetwindow_t) == 196, "Invalid 'targetwindow_t' structure size detected!");

} // namespace Ashita::FFXI

// Ashita.h: resources.
struct IAbility
{
    uint16_t Id;              // The abilities id.
    uint8_t Type;             // The abilities type.
    uint8_t Element;          // The abilities element.
    uint16_t ListIconId;      // The abilities list icon id.
    uint16_t ManaCost;        // The abilities mana cost.
    uint16_t RecastTimerId;   // The abilities recast timer id.
    uint16_t Targets;         // The abilities valid targets.
    int16_t TPCost;           // The abilities TP cost.
    uint8_t MenuCategoryId;   // The abilities sub-category menu id.
    uint8_t MonsterLevel;     // The abilities monster level.
    int8_t Range;             // The abilities range. (Range is based on a lookup table.)
    uint8_t AreaRange;        // The abilities AoE range.  (Range is based on a lookup table.)
    uint8_t AreaShapeType;    // The abilities AoE shape.  (0 = None, 1 = Circle on self/target, 2 = Cone AoE, 3 = Circle on self while targeting enemy.)
    uint8_t CursorTargetType; // The abilities cursor target type. (0x00 to 0x0F flag determining the valid targeting type of the ability.)
    uint8_t Unknown0000;      // Unknown
    uint8_t Unknown0001;      // Unknown (Type confirmed.)
    uint16_t Unknown0002;     // Unknown (Type confirmed.)
    uint16_t Unknown0003;     // Unknown (Type confirmed.) (TP related.)
    uint16_t Unknown0004;     // Unknown (Type confirmed.) (TP related.)
    uint16_t Unknown0005;     // Unknown (Type confirmed.)
    uint16_t Unknown0006;     // Unknown (Type confirmed.)
    uint16_t Unknown0007;     // Unknown
    uint16_t Unknown0008;     // Unknown (Type confirmed.)
    uint8_t Unknown0009[11];  // Unknown
    uint8_t EOE;              // 0xFF - End of Entry

    const char* Name[3];        // The abilities name. (0 = Default, 1 = Japanese, 2 = English)
    const char* Description[3]; // The abilities description. (0 = Default, 1 = Japanese, 2 = English)
};

struct ISpell
{
    uint16_t Index;            // The spells index.
    uint16_t Type;             // The spells type.
    uint16_t Element;          // The spells element.
    uint16_t Targets;          // The spells valid targets.
    uint16_t Skill;            // The spells magic skill type.
    uint16_t ManaCost;         // The spells mana cost.
    uint8_t CastTime;          // The spells cast time.         (CastTime / 4.0) (Cast Bar: CastTime * 20)
    uint8_t RecastDelay;       // The spells recast delay.      (RecastDely / 4.0) (Cast Bar: RecastDelay * 15)
    int16_t LevelRequired[24]; // The spells level requirements.(-1 = Unlearnable, > 99 = Unlocked with job points. See: JobPointMask for validation.)
    uint16_t Id;               // The spells id.                (Old recast id; unused now except for auto-sorting.)
    uint16_t ListIconNQ;       // The spells icon id.           (Low quality menu icon, client config set to icon set 1.)
    uint16_t ListIconHQ;       // The spells icon id.           (High quality menu icon, client config set to icon set 2.)
    uint8_t Requirements;      // The spells requirements.
    int8_t Range;              // The spells casting range.     (Range is based on a lookup table.)
    uint8_t AreaRange;         // The spells AoE range.         (Range is based on a lookup table.)
    uint8_t AreaShapeType;     // The spells AoE shape.         (0 = None, 1 = Circle on self/target, 2 = Cone AoE, 3 = Circle on self while targeting enemy.)
    uint8_t CursorTargetType;  // The spells AoE target type.   (0x00 to 0x0F flag determining the valid targeting type of the spell.)
    uint8_t Unknown0000[3];    // Unknown                       (Always 00 for all spells.)
    uint32_t AreaFlags;        // The spells AoE flags.         (Flag to determine various things. Example: Divine Veil valid spell: ((val & 0x7FFF80) == 512)))
    uint16_t Unknown0001;      // Unknown
    uint8_t Unknown0002;       // Unknown
    uint8_t Unknown0003;       // Unknown                       (Type confirmed.) (Used with GEO spells, looks to be a range of some sort.)
    uint8_t Unknown0004[8];    // Unknown
    uint32_t JobPointMask;     // The spells job point mask.    (JobPointMask & (1 << ((PlayerJobU32 & 0xFF) & 0x1F))) (If true, LevelRequired turns into required job points to unlock the spell.)
    uint8_t Unknown0005[3];    // Unknown
    uint8_t EOE;               // 0xFF - End of Entry

    const char* Name[3];        // The spells name. (0 = Default, 1 = Japanese, 2 = English)
    const char* Description[3]; // The spells description. (0 = Default, 1 = Japanese, 2 = English)
};

struct IMonAbility
{
    uint16_t AbilityId;  // The monstrosity ability id.
    int8_t Level;        // The monstrosity ability level.
    uint8_t Unknown0000; // Unknown
};

struct IItem
{
    // Common Item Header
    uint32_t Id;         // The items id.
    uint16_t Flags;      // The items flags.
    uint16_t StackSize;  // The items stack size.
    uint16_t Type;       // The items type.
    uint16_t ResourceId; // The items resource id. (Mainly used for AH sorting.)
    uint16_t Targets;    // The items valid targets for use.

    // Armor & Weapon Items
    uint16_t Level;               // The items level requirement to use.
    uint16_t Slots;               // The items equipment slots where the item can be equipped to.
    uint16_t Races;               // The items races that can use the item.
    uint32_t Jobs;                // The items jobs that can use the item.
    uint16_t SuperiorLevel;       // The items superior level.
    uint16_t ShieldSize;          // The items shield size.
    uint8_t MaxCharges;           // The items max charges.
    uint16_t CastTime;            // The items cast time.
    uint16_t CastDelay;           // The items cast delay.
    uint32_t RecastDelay;         // The items recast delay.
    uint16_t BaseItemId;          // The items base item id used for upgrades.
    uint16_t ItemLevel;           // The items item level.
    uint16_t Damage;              // The items damage.
    uint16_t Delay;               // The items delay.
    uint16_t DPS;                 // The items damae per second.
    uint8_t Skill;                // The items skill type.
    uint8_t JugSize;              // The items jug size.
    uint32_t WeaponUnknown0000;   // Unknown (Some sort of flag for item types. 0-5 and 255 are valid values.)
    uint8_t Range;                // The items range.           (Range is based on a lookup table.)
    uint8_t AreaRange;            // The items AoE range.       (Range is based on a lookup table.)
    uint8_t AreaShapeType;        // The items AoE shape.       (0 = None, 1 = Circle on self/target, 2 = Cone AoE, 3 = Circle on self while targeting enemy.)
    uint8_t AreaCursorTargetType; // The items AoE target type. (0x00 to 0x0F flag determining the valid targeting type of the spell.)

    // Common Items
    uint16_t Element;         // The items elemental aura type.
    uint32_t Storage;         // The items storage amount.
    uint32_t AttachmentFlags; // The items puppet attachment flags.

    // Instinct Items
    uint16_t InstinctCost; // The items instinct cost.

    // Monstrosity Items
    uint16_t MonstrosityId;                 // The items monstrosity id.
    char MonstrosityName[0x20];             // The items monstrosity name.
    uint8_t MonstrosityData[0x0A];          // The items monstrosity data. (Unknown block of data currently.)
    IMonAbility MonstrosityAbilities[0x10]; // The items monstrosity abilities.

    // Puppet Items
    uint16_t PuppetSlotId;   // The items puppet slot id.
    uint32_t PuppetElements; // The items puppet elements.

    // Slip & Voucher Items
    uint8_t SlipData[0x46]; // The items slip data.

    // Usable Items
    uint16_t UsableData0000; // The items usable data. (0) - (Used as animation lookup types. Learnable Scrolls: 0x01000. Learnable Rolls: 0x02000)
    uint32_t UsableData0001; // The items usable data. (1) - (Used as animation ids for learnable items. Used as AoE range information for usable items.)
    uint32_t UsableData0002; // The items usable data. (2) - (Used as a flag to tell what UsableData0001 is. 0x00: Unused. 0x01: Animation Id. 0x02: AoE range information.)

    uint32_t Article; // The items article type.

    const char* Name[3];            // The items name. (0 = Default, 1 = Japanese, 2 = English)
    const char* Description[3];     // The items description. (0 = Default, 1 = Japanese, 2 = English)
    const char* LogNameSingular[3]; // The items log name (singular). (0 = Default, 1 = Japanese, 2 = English)
    const char* LogNamePlural[3];   // The items log name (plural). (0 = Default, 1 = Japanese, 2 = English)

    uint32_t ImageSize;      // The items image size.
    uint8_t ImageType;       // The items image type.
    uint8_t ImageName[0x10]; // The items image name.
    uint8_t Bitmap[0x980];   // The items bitmap data.
};

struct IStatusIcon
{
    uint16_t Index;    // The status icons index in the DAT file.
    uint16_t Id;       // The status icons id. (Most match the index, but some don't.)
    uint8_t CanCancel; // The status icons cancellable flag. (1 if it can be cancelled, 0 otherwise.)
    uint8_t HideTimer; // The status icons force-hide timer flag. (1 if the timer is hidden by force, 0 otherwise.)

    const char* Description[3]; // The status icons description. (0 = Default, 1 = Japanese, 2 = English)

    uint32_t ImageSize;      // The status icons image size.
    uint8_t ImageType;       // The status icons image type.
    uint8_t ImageName[0x10]; // The status icons image name.
    uint8_t Bitmap[0x156A];  // The status icons bitmap data.
};

